#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("liczby.txt");
    int n;
    int minP = 1000000, maxN = -1;
    int ileP = 0, ileN = 0;
    while (plik >> n) {
        if (n % 2 == 0) {
            if (n < minP) minP = n;
            ileP++;
        } else {
            if (n > maxN) maxN = n;
            ileN++;
        }
    }
    cout << "Min wsrod parzystych: " << minP << " (z " << ileP << " parzystych)" << endl;
    cout << "Max wsrod nieparzystych: " << maxN << " (z " << ileN << " nieparzystych)" << endl;
    return 0;
}
```

